script:
(function () {
  'use strict';
  // Gross income needed for a mortgage under front-end / back-end debt-to-income (DTI) limits.
  //   Loan L = price - down payment. P&I = L * i / (1 - (1 + i)^-n), i = rate / 12 (L / n at 0%).
  //   Housing H = P&I + property tax / 12 + insurance / 12 + HOA + PMI (PMI = rate * L / 12 when L > 80% of price).
  //   Monthly income needed = max(H / front%, (H + other debts) / back%); annual = 12 x monthly.
  // Checked in Node (scratchpad tests/w3b3_mri.test.js) against an independent Python computation:
  //   $400,000 price, $80,000 down, 6.5%, 30 yrs -> P&I $2,022.62; + $4,400/yr tax + $1,800/yr insurance
  //   = $2,539.28/mo; 28% front-end -> $9,068.87/mo = $108,826/yr (binds over 36% back-end with $400 debts
  //   -> $97,976/yr); $20,000 down adds 0.5% PMI -> $3,076.86/mo, $131,865/yr;
  //   PMI appears only under 20% down; 0% rate gives L / n; blank or invalid input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var PRESETS = { conventional: [28, 36], fha: [31, 43] };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pi(loan, i, n) {
    if (loan <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  function housing(o, rate) {
    var loan = Math.max(0, o.price - o.down);
    var c = {
      loan: loan,
      pi: pi(loan, rate / 100 / 12, o.term * 12),
      tax: o.tax / 12,
      ins: o.ins / 12,
      pmi: loan > 0.8 * o.price ? o.pmi / 100 * loan / 12 : 0,
      hoa: o.hoa
    };
    c.total = c.pi + c.tax + c.ins + c.pmi + c.hoa;
    c.byFront = c.total / (o.front / 100);
    c.byBack = (c.total + o.debts) / (o.back / 100);
    c.needed = Math.max(c.byFront, c.byBack);
    return c;
  }

  function syncPreset(e) {
    var t = e && e.target ? e.target.id : '';
    if (t === 'mriPreset') {
      var p = PRESETS[el('mriPreset').value];
      if (p) { el('mriFront').value = String(p[0]); el('mriBack').value = String(p[1]); }
    } else if (t === 'mriFront' || t === 'mriBack') {
      var f = read('mriFront'), b = read('mriBack'), match = 'custom';
      Object.keys(PRESETS).forEach(function (k) { if (PRESETS[k][0] === f && PRESETS[k][1] === b) match = k; });
      el('mriPreset').value = match;
    }
  }

  function clearResults() {
    ['mriIncome', 'mriMonthly', 'mriHousing', 'mriLoan', 'mriBinding', 'mriPI', 'mriTaxM', 'mriInsM', 'mriPmiM',
     'mriHoaM', 'mriByFront', 'mriByBack'].forEach(function (id) { setText(id, '–'); });
    el('mriRates').innerHTML = '';
  }

  function update(e) {
    syncPreset(e);
    var o = {
      price: read('mriPrice'), down: read('mriDown', true), rate: read('mriRate'), term: parseInt(el('mriTerm').value, 10),
      tax: read('mriTax', true), ins: read('mriIns', true), hoa: read('mriHoa', true), pmi: read('mriPmi', true),
      debts: read('mriDebts', true), front: read('mriFront'), back: read('mriBack')
    };
    var error = el('mriError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(o.down) || o.down < 0) msg = 'The down payment cannot be negative.';
    else if (o.down >= o.price) msg = 'The down payment must be less than the home price.';
    else if (isNaN(o.rate) || o.rate < 0 || o.rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (!(o.term > 0)) msg = 'Choose a loan term.';
    else if ([o.tax, o.ins, o.hoa, o.pmi, o.debts].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Costs, PMI and debts cannot be negative.';
    else if (o.pmi > 5) msg = 'Enter a PMI rate up to 5% a year.';
    else if (isNaN(o.front) || isNaN(o.back) || o.front <= 0 || o.back <= 0 || o.front > 100 || o.back > 100) msg = 'Enter front-end and back-end ratios between 1% and 100%.';
    var hint = el('mriDownHint');
    if (!isNaN(o.price) && o.price > 0 && !isNaN(o.down) && o.down >= 0) {
      hint.textContent = (Math.round(o.down / o.price * 1000) / 10) + '% of the price.' + (o.down < 0.2 * o.price ? ' Under 20%, so PMI applies.' : '');
    } else hint.textContent = '';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var c = housing(o, o.rate);
    setText('mriIncome', money0.format(c.needed * 12));
    setText('mriMonthly', money.format(c.needed));
    setText('mriHousing', money.format(c.total));
    setText('mriLoan', money0.format(c.loan));
    setText('mriPI', money.format(c.pi));
    setText('mriTaxM', money.format(c.tax));
    setText('mriInsM', money.format(c.ins));
    setText('mriPmiM', money.format(c.pmi));
    setText('mriHoaM', money.format(c.hoa));
    setText('mriByFrontLabel', 'Front-end ' + o.front + '% (housing only)');
    setText('mriByBackLabel', 'Back-end ' + o.back + '% (housing + debts)');
    setText('mriByFront', money0.format(c.byFront * 12) + ' / yr');
    setText('mriByBack', money0.format(c.byBack * 12) + ' / yr');

    var note;
    if (c.byFront >= c.byBack) {
      note = 'The front-end limit sets the income you need: the ' + money.format(c.total) + ' housing payment must be no more than ' +
        o.front + '% of your gross monthly income. Your other debts are low enough not to change the answer.';
    } else {
      note = 'The back-end limit sets the income you need: housing plus your ' + money.format(o.debts) + ' of other monthly debts must be no more than ' +
        o.back + '% of gross monthly income. Every $100 a month of debt you pay off lowers the income needed by about ' +
        money0.format(100 / (o.back / 100) * 12) + ' a year, down to the front-end figure.';
    }
    setText('mriBinding', note);

    var out = [];
    for (var k = -3; k <= 3; k++) {
      var r = Math.round((o.rate + k * 0.5) * 1000) / 1000;
      if (r < 0 || r > 30) continue;
      var cr = housing(o, r);
      var mark = k === 0 ? ' (yours)' : '';
      out.push('<tr><td>' + r + '%' + mark + '</td><td>' + money.format(cr.pi) + '</td><td>' + money.format(cr.total) + '</td><td>' +
        money0.format(cr.needed * 12) + '</td></tr>');
    }
    el('mriRates').innerHTML = out.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mriForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
